generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?triggeredAction (AVG(xsd:decimal(?actionAmount)) AS ?avgActionAmount)
WHERE {
  {
    SELECT ?investorId ?month WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:date ?date .
      BIND(STR(?date) AS ?dateStr)
      BIND(SUBSTR(?dateStr,1,7) AS ?month)   # assumes format YYYY-MM...
    }
    GROUP BY ?investorId ?month
  }
  {
    SELECT ?investorId ?triggeredAction WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:triggeredAction ?triggeredAction .
    }
    GROUP BY ?investorId ?triggeredAction
  }
  {
    SELECT ?investorId ?actionAmount WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?actionAmount .
    }
  }
}
GROUP BY ?month ?triggeredAction

